package tech.lightclient.modules.impl.utils;import tech.lightclient.LightClient;import tech.lightclient.client.events.impl.client.EventKey;import tech.lightclient.client.events.impl.client.UpdateEvent;import tech.lightclient.client.utils.client.ILogger;import tech.lightclient.client.utils.eventbus.EventHandler;import tech.lightclient.client.utils.globals.GlobalsManager;import tech.lightclient.modules.api.Category;import tech.lightclient.modules.api.Function;import tech.lightclient.modules.api.FunctionAdd;import tech.lightclient.modules.api.settings.impl.BindSetting;import tech.lightclient.modules.api.settings.impl.BooleanSetting;import net.minecraft.util.Formatting;@FunctionAdd(name = "Globals", alias = "Globals", category = Category.Utilities, description = "Группа, общие точки с друзья")public class Globals extends Function implements ILogger {    public static final BindSetting pointBind = new BindSetting("Бинд точки", 0);    public static final BooleanSetting autoConnect = new BooleanSetting("Авто-подключение", true);    public static final BooleanSetting customTextureSync = new BooleanSetting("Синхронизация кастомных текстурок", false);    private final GlobalsManager manager = GlobalsManager.getInstance();    private long lastHeartbeat;    private long lastInventorySync;    public Globals() {        addSettings(pointBind, autoConnect, customTextureSync);    }    @Override    public void onEnable() {        super.onEnable();    }    @Override    public void onDisable() {        manager.disconnect();        super.onDisable();    }    @EventHandler    public void onTick(UpdateEvent event) {        manager.setCustomTextureSyncEnabled(customTextureSync.get());        long now = System.currentTimeMillis();        if (now - lastHeartbeat >= 3000L) {            manager.heartbeat();            lastHeartbeat = now;        }        if (now - lastInventorySync >= 1500L) {            manager.syncInventory();            lastInventorySync = now;        }    }    @EventHandler    public void onKey(EventKey event) {        if (LightClient.isHide()) return;        if (event.getAction() == 1 && event.isKeyDown(pointBind.get())) {            manager.createPoint();            logDirect("Точка успешно поставлена", Formatting.GRAY);        }    }    public static GlobalsManager manager() {        return GlobalsManager.getInstance();    }}